import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"鹹","description":"周易正义 - 鹹","frontmatter":{"title":"鹹","description":"周易正义 - 鹹"},"headers":[],"relativePath":"zh/classics/zhengyi/031.md","filePath":"zh/classics/zhengyi/031.md"}'),l={name:"zh/classics/zhengyi/031.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>泽山咸</p></blockquote><blockquote><p>卦辞：亨，利贞，取女吉。</p></blockquote><blockquote><p>彖曰：咸，感也。柔上而刚下，二气感应以相与，止而说，男下女，是以亨利贞，取女吉也。天地感而万物化生，圣人感人心而天下和平；观其所感，而天地万物之情可见矣！</p></blockquote><h1 id="鹹" tabindex="-1">鹹 <a class="header-anchor" href="#鹹" aria-label="Permalink to “鹹”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>“咸亨”至“取女吉”。○正义曰：先儒以《易》之旧题，分自此以上三十卦为《上经》，已下三十四卦为《下经》，《序卦》至此又别起端首。先儒皆以《上经》明天道，《下经》明人事，然韩康伯注《序卦》破此义云：“夫《易》，六画成卦，三才必备，错综天人，以效变化，岂有天道、人事偏於上下哉！”案：《上经》之内，明饮食必有讼，讼必有众起，是兼於人事，不专天道。既不专天道，则《下经》不专人事，理则然矣。但孔子《序卦》不以咸系离。《系辞》云“二篇之策”，则是六十四卦旧分上下，乾、坤象天地，咸、恒明夫妇。乾坤乃造化之本，夫妇实人伦之原，因而拟之，何为不可？天地各卦，夫妇共卦者，周氏云：“尊天地之道，略於人事，犹如三才，天地为二，人止为一也。”此必不然。窃谓乾、坤明天地初辟，至屯乃刚柔始交。故以纯阳象天，纯阴象地，则咸以明人事。人物既生，共相感应。若二气不交，则不成於相感，自然天地各一，夫妇共卦。此不言可悉，岂宜妄为异端！“咸亨利贞取女吉”者，“咸”感也。此卦明人伦之始，夫妇之义，必须男女共相感应，方成夫妇。既相感应，乃得亨通。若以邪道相通，则凶害斯及，故利在贞正。既感通以正，即是婚媾之善，故云“咸亨利贞取女吉”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="咸-感也。柔上而刚下-二气感应以相与。-​" tabindex="-1">咸，感也。柔上而刚下，二气感应以相与。 ​ <a class="header-anchor" href="#咸-感也。柔上而刚下-二气感应以相与。-​" aria-label="Permalink to “咸，感也。柔上而刚下，二气感应以相与。 ​”">​</a></h3><p>王弼：是以亨也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“柔上而刚下，二气感应以相与”者，此因上下二体，释“咸亨”之义也。艮刚而兑柔，若刚自在上，柔自在下，则不相交感，无由得通。今兑柔在上而艮刚在下，是二气感应以相授与，所以为“咸亨”也。</p><h3 id="止而说-​" tabindex="-1">止而说， ​ <a class="header-anchor" href="#止而说-​" aria-label="Permalink to “止而说， ​”">​</a></h3><p>王弼：故“利贞”也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此因二卦之义释“利贞”也。艮止而兑，说也。能自静止则不随动欲，以上行说，则不为邪谄。不失其正，所以“利贞”也。</p><h3 id="男下女-​" tabindex="-1">男下女， ​ <a class="header-anchor" href="#男下女-​" aria-label="Permalink to “男下女， ​”">​</a></h3><p>王弼：“取女吉”也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此因二卦之象释“取女吉”之义。艮为少男而居於下，兑为少女而处於上，是男下於女也。婚姻之义，男先求女，亲迎之礼，御轮三周，皆男先下於女，然后女应於男，所以取女得吉者也。</p><h3 id="是以-亨-利贞-取女吉-也。天地感而万物化生-​" tabindex="-1">是以“亨，利贞”，“取女吉”也。天地感而万物化生， ​ <a class="header-anchor" href="#是以-亨-利贞-取女吉-也。天地感而万物化生-​" aria-label="Permalink to “是以“亨，利贞”，“取女吉”也。天地感而万物化生， ​”">​</a></h3><p>王弼：二气相与，乃“化生”也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>“是以”至“化生”。○正义曰：“是以亨利贞取女吉”者，次第释讫，总举《繇》辞以结之。“天地感而万物化生”者，以下广明感之义也。天地二气，若不感应相与，则万物无由得应化而生。</p><h3 id="圣人感人心而天下和平。观其所感-而天地万物之情可见矣。-​" tabindex="-1">圣人感人心而天下和平。观其所感，而天地万物之情可见矣。 ​ <a class="header-anchor" href="#圣人感人心而天下和平。观其所感-而天地万物之情可见矣。-​" aria-label="Permalink to “圣人感人心而天下和平。观其所感，而天地万物之情可见矣。 ​”">​</a></h3><p>王弼：天地万物之情，见於所感也。凡感之为道，不能感非类者也，故引取女以明同类之义也。同类而不相感应，以其各亢所处也，故女虽应男之物，必下之而后取女乃吉也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>“圣人”至“可见矣”。○正义曰：“圣人感人心而天下和平”者，圣人设教，感动人心，使变恶从善，然后天下和平。“观其所感而天地万物之情可见矣”者，结叹咸道之广，大则包天地，小则该万物。感物而动，谓之情也。天地万物皆以气类共相感应，故“观其所感，而天地万物之情可见矣”。</p><h2 id="《象》曰-山上有泽-咸。君子以虚受人。-​" tabindex="-1">《象》曰：山上有泽，咸。君子以虚受人。 ​ <a class="header-anchor" href="#《象》曰-山上有泽-咸。君子以虚受人。-​" aria-label="Permalink to “《象》曰：山上有泽，咸。君子以虚受人。 ​”">​</a></h2><p>王弼：以虚受人，物乃感应。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰”至“虚受人”。○正义曰：“山上有泽，咸”，泽性下流，能润於下；山体上承，能受其润。以山感泽，所以为“咸”。“君子以虚受人”者，君子法此咸卦，下山上泽，故能空虚其怀，不自有实，受纳於物，无所弃遗，以此感人，莫不皆应。</p><h2 id="初六-咸其拇。-​" tabindex="-1">初六：咸其拇。 ​ <a class="header-anchor" href="#初六-咸其拇。-​" aria-label="Permalink to “初六：咸其拇。 ​”">​</a></h2><p>王弼：处咸之初，为感之始，所感在末，故有志而已。如其本实，未至伤静。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>“初六咸其拇”。○正义曰：“咸其拇”者，拇是足大指也，体之最末。初应在四，俱处卦始，为感浅末，取譬一身，在於足指而已，故曰“咸其拇”也。○注“处咸”至“伤静”。○正义曰：六二《咸》道转进，所感在腓。腓体动躁，则成往而行。今初六所感浅末，则譬如拇指，指虽小动，未移其足，以喻人心初感，始有其志。志虽小动，未甚躁求。凡吉凶悔吝，生乎动者也。以其本实未伤於静，故无吉凶悔吝之辞。</p><h3 id="《象》曰-咸其拇-志在外也。-​" tabindex="-1">《象》曰：“咸其拇”，志在外也。 ​ <a class="header-anchor" href="#《象》曰-咸其拇-志在外也。-​" aria-label="Permalink to “《象》曰：“咸其拇”，志在外也。 ​”">​</a></h3><p>王弼：四属外也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“志在外”者，外谓四也。与四相应，所感在外，处於感初，有志而已，故云“志在外也”。</p><h2 id="六二-咸其腓-凶。居吉。-​" tabindex="-1">六二：咸其腓，凶。居吉。 ​ <a class="header-anchor" href="#六二-咸其腓-凶。居吉。-​" aria-label="Permalink to “六二：咸其腓，凶。居吉。 ​”">​</a></h2><p>王弼：咸道转进，离拇升腓，腓体动躁者也。感物以躁，凶之道也。由躁故凶，居则吉矣。处不乘刚，故可以居而获吉。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>“六二”至“居吉”。○正义曰：腓，足之腓肠也。六二应在九五，咸道转进，离拇升腓，腓体动躁，躁以相感，凶之道也。由躁故凶，静居则吉，故曰“咸其腓凶居吉”。以不乘刚，故可以居而获吉。○注“腓体动躁”。○正义曰：王廙云：动於腓肠，斯则行矣。故言“腓体动躁”也。</p><h3 id="《象》曰-虽凶居吉-顺不害也。-​" tabindex="-1">《象》曰：虽凶居吉，顺不害也。 ​ <a class="header-anchor" href="#《象》曰-虽凶居吉-顺不害也。-​" aria-label="Permalink to “《象》曰：虽凶居吉，顺不害也。 ​”">​</a></h3><p>王弼：阴而为居，顺之道也。不躁而居，顺不害也。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“虽”者，与夺之辞。若既凶矣，何由得居而获吉？良由阴性本静。今能不躁而居，顺其本性，则不有灾害，免凶而获吉也。</p><h2 id="九三-咸其股-执其随-往吝。-​" tabindex="-1">九三：咸其股，执其随，往吝。 ​ <a class="header-anchor" href="#九三-咸其股-执其随-往吝。-​" aria-label="Permalink to “九三：咸其股，执其随，往吝。 ​”">​</a></h2><p>王弼：股之为物，随足者也。进不能制动，退不能静处，所感在股，“志在随人”者也。“志在随人”，所执亦以贱矣。用斯以往，吝其宜也。</p><h3 id="《象》曰-咸其股-亦不处也。志在随人-所执下也。-​" tabindex="-1">《象》曰：“咸其股”，亦不处也。志在随人，所执下也。 ​ <a class="header-anchor" href="#《象》曰-咸其股-亦不处也。志在随人-所执下也。-​" aria-label="Permalink to “《象》曰：“咸其股”，亦不处也。志在随人，所执下也。 ​”">​</a></h3><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“咸其股亦不处也”者，非但进不能制动，退亦不能静处也。“所执下”者，既“志在随人”，是其志意所执下贱也。</p><h2 id="九四-贞吉-悔亡。憧憧往来-朋从尔思。-​" tabindex="-1">九四：贞吉，悔亡。憧憧往来，朋从尔思。 ​ <a class="header-anchor" href="#九四-贞吉-悔亡。憧憧往来-朋从尔思。-​" aria-label="Permalink to “九四：贞吉，悔亡。憧憧往来，朋从尔思。 ​”">​</a></h2><p>王弼：处上卦之初，应下卦之始，居体之中，在股之上，二体始相交感，以通其志，心神始感者也。凡物始感而不以之於正，则至於害，故必贞然后乃吉，吉然后乃得亡其悔也。始在於感，未尽感极，不能至於无思以得其党，故有“憧憧往来”，然后“朋从其思”也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“贞吉悔亡”者，九四居“上卦之初，应下卦之始，居体之中，在股之上，二体始相交感，以通其志，心神始感者也。凡物始感而不以之於正”，则害之将及矣。“故必贞然后乃吉，吉然后乃得亡其悔也”。故曰“贞吉悔亡”也。“憧憧往来，朋从尔思”者，“始在於感，未尽感极”，惟欲思运动以求相应，未能忘怀息照，任夫自然，故有“憧憧往来”，然后朋从尔之所思也。</p><h3 id="《象》曰-贞吉-悔亡-未感害也。-​" tabindex="-1">《象》曰：“贞吉，悔亡”，未感害也。 ​ <a class="header-anchor" href="#《象》曰-贞吉-悔亡-未感害也。-​" aria-label="Permalink to “《象》曰：“贞吉，悔亡”，未感害也。 ​”">​</a></h3><p>王弼：未感於害，故可正之，得“悔亡”也。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“未感害”者，心神始感，未至於害，故不可不正，正而故得“悔亡”也。</p><h3 id="憧憧往来-未光大也。-​" tabindex="-1">“憧憧往来”，未光大也。 ​ <a class="header-anchor" href="#憧憧往来-未光大也。-​" aria-label="Permalink to ““憧憧往来”，未光大也。 ​”">​</a></h3><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“未光大”者，非感之极，不能无思无欲，故未光大也。</p><h2 id="九五-咸其脢-无悔。-​" tabindex="-1">九五：咸其脢，无悔。 ​ <a class="header-anchor" href="#九五-咸其脢-无悔。-​" aria-label="Permalink to “九五：咸其脢，无悔。 ​”">​</a></h2><p>王弼：“脢”者，心之上，口之下，进不能大感，退亦不为无志，其志浅末，故“无悔”而已。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>“九五”至“无悔”。○正义曰：“咸其脢无悔”者，“脢”者心之上，口之下也。四已居体之中，为心神所感，五进在於四上，故所感在脢，脢已过心，故“进不能大感”，由在心上，“退亦不能无志”，志在浅末，故“无悔”而已，故曰：“咸其脢无悔”也。○注“脢者心之上口之下”。○正义曰：“脢者心之上口之下”者，子夏《易传》曰：“在脊曰脢。”马融云：“脢，背也。”郑玄云：“脢，脊肉也”。王肃云：“脢在背而夹脊。”《说文》云：“脢，背肉也。”虽诸说不同，大体皆在心上。辅嗣以四为心神，上为辅颊，五在上四之间，故直云“心之上口之下”也。明其浅於心神，厚於言语。</p><h3 id="《象》曰-咸其脢-志末也。-​" tabindex="-1">《象》曰：“咸其脢”，志末也。 ​ <a class="header-anchor" href="#《象》曰-咸其脢-志末也。-​" aria-label="Permalink to “《象》曰：“咸其脢”，志末也。 ​”">​</a></h3><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“志末也”者，末犹浅也，感以心为深，过心则谓之浅末矣。</p><h2 id="上六-咸其辅、颊、舌。-​" tabindex="-1">上六：咸其辅、颊、舌。 ​ <a class="header-anchor" href="#上六-咸其辅、颊、舌。-​" aria-label="Permalink to “上六：咸其辅、颊、舌。 ​”">​</a></h2><p>王弼：咸道转末，故在口舌言语而已。</p><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“咸其辅颊舌”者，马融云：“辅，上颔也。”“辅、颊、舌”者，言语之具。咸道转末，在於口舌言语而已，故云“咸其辅颊舌”也。</p><h3 id="《象》曰-咸其辅、颊、舌-滕口说也。-​" tabindex="-1">《象》曰：“咸其辅、颊、舌”，滕口说也。 ​ <a class="header-anchor" href="#《象》曰-咸其辅、颊、舌-滕口说也。-​" aria-label="Permalink to “《象》曰：“咸其辅、颊、舌”，滕口说也。 ​”">​</a></h3><p>王弼：“辅、颊、舌”者，所以为语之具也。“咸其辅颊舌”，则“滕口说”也。“憧憧往来”，犹未光大，况在滕口，薄可知也。</p><h3 id="疏-18" tabindex="-1">疏 <a class="header-anchor" href="#疏-18" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“滕口说也”者，旧说字作“滕”，徒登反。滕，竞与也。所竞者口，无复心实，故云“滕口说”也。郑玄又作“媵”。媵，送也。《咸》道极薄，徒送口舌言语相感而已，不复有志於其閒。王《注》义得两通，未知谁同其旨也。</p>',78)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
